import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
	static final long MOD = 998244353L;
	static long[] fac;

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.ni();
		long K = sc.nl();
		if (K >= N) {
			pw.println(0);
			pw.close();
			return;
		}
		int C = (int)(N - K);

		fac = new long[200001];
		fac[0] = 1L;
		IntStream.rangeClosed(1, 200000).forEach(i -> fac[i] = (i * fac[i-1]) % MOD);

		long ans = 0L;
		int sign = 1;
		for (int i = C; i >= 1; i--) {
			long val = (choose(C, i) * power(i, N, MOD)) % MOD;
			ans = (ans + sign * val) % MOD;
			if (ans < 0) ans += MOD;
			sign = -sign;
		}

		long mult = (C == N) ? 1L : (2L * choose(N, C)) % MOD;
		pw.println((ans * mult) % MOD);

		pw.close();
	}

	public static long choose(int n, int k) {
		long den = (fac[k] * fac[n-k]) % MOD;
		long denInv = power(den, MOD - 2, MOD);
		return (fac[n] * denInv) % MOD;
	}

	public static long power(long x, long y, long m) {
		return BigInteger.valueOf(x).modPow(BigInteger.valueOf(y), BigInteger.valueOf(m)).longValue();
	}

	static class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int ni() { return Integer.parseInt(next()); }

		long nl() { return Long.parseLong(next()); }

		double nd() { return Double.parseDouble(next()); }

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}
}
